-- SaiSai v3 · seed (T04) = ข้อมูลชุดเดียวกับ legacy/db/init/02-seed.sql ทุกแถว (คัดลอก INSERT ตรงตัว)
-- + วันหยุดโรงงาน 3 วัน (legacy 04/06) + doc_counters ต่อจาก seed (SO 18 · CL 4 · SR 3 · QT 0) + app_settings.now
-- reset_test_data(p_now) ใช้ทั้งตอน init (ท้ายไฟล์) และ POST /api/test/reset
--   ล้าง: ข้อมูลธุรกิจทั้งหมด + quotes · notifications · chat_sessions · chat_messages · tts_audio
--   ไม่ล้าง: docs · doc_chunks · eval_runs · load_runs · app_settings key อื่นที่ไม่ใช่ 'now'
--   p_now NULL = ใช้เวลาจริง (ลบแถว app_settings 'now')
--   hook: งานอื่นสร้างฟังก์ชัน public.reset_hook_<ชื่อ>() (ไม่มีอาร์กิวเมนต์) ใน migration ของตัวเอง → ถูกเรียกท้าย reset ตามลำดับชื่อ
-- รหัสผ่านเก็บเป็น bcrypt hash เท่านั้น (รหัสทดสอบดู legacy/web/SPEC.md ข้อ 6)
SET client_min_messages = warning;
SET client_encoding = 'UTF8';
SET TIME ZONE 'Asia/Bangkok';

CREATE OR REPLACE FUNCTION reset_test_data(p_now TIMESTAMPTZ DEFAULT '2026-10-11T10:00:00+07:00')
RETURNS JSONB LANGUAGE plpgsql SET search_path = public AS $fn$
DECLARE
  v_counts JSONB;
  r RECORD;
BEGIN
  -- กัน reset สองครั้งชนกัน
  PERFORM pg_advisory_xact_lock(4604);
  -- ปิด trigger ห้ามแก้/ลบ เฉพาะภายในฟังก์ชันนี้ (transaction เดียวกัน)
  ALTER TABLE order_status_history DISABLE TRIGGER USER;
  ALTER TABLE claim_status_history DISABLE TRIGGER USER;
  ALTER TABLE payments DISABLE TRIGGER USER;
  ALTER TABLE order_pickup_change DISABLE TRIGGER USER;
  TRUNCATE order_pickup_change, claim_status_history, claim_photos, claims, payments, order_status_history, orders,
           sample_request_items, sample_requests, delivery_addresses, users, companies,
           products, product_models, factory_holiday, doc_counters, shop_settings,
           quotes, notifications, chat_messages, chat_sessions, tts_audio RESTART IDENTITY CASCADE;
  ALTER TABLE order_status_history ENABLE TRIGGER USER;
  ALTER TABLE claim_status_history ENABLE TRIGGER USER;
  ALTER TABLE payments ENABLE TRIGGER USER;
  ALTER TABLE order_pickup_change ENABLE TRIGGER USER;

  DELETE FROM app_settings WHERE key = 'now';
  IF p_now IS NOT NULL THEN
    VALUES ('now', to_char(p_now AT TIME ZONE 'Asia/Bangkok', 'YYYY-MM-DD"T"HH24:MI:SS') || '+07:00');
  END IF;












  -- ให้ identity ต่อจากค่าสูงสุด
  PERFORM setval(pg_get_serial_sequence('companies', 'id'), (SELECT max(id) FROM companies));
  PERFORM setval(pg_get_serial_sequence('users', 'id'), (SELECT max(id) FROM users));
  PERFORM setval(pg_get_serial_sequence('delivery_addresses', 'id'), (SELECT max(id) FROM delivery_addresses));
  PERFORM setval(pg_get_serial_sequence('products', 'id'), (SELECT max(id) FROM products));
  PERFORM setval(pg_get_serial_sequence('orders', 'id'), (SELECT max(id) FROM orders));
  PERFORM setval(pg_get_serial_sequence('payments', 'id'), (SELECT max(id) FROM payments));
  PERFORM setval(pg_get_serial_sequence('order_status_history', 'id'), (SELECT max(id) FROM order_status_history));
  PERFORM setval(pg_get_serial_sequence('claims', 'id'), (SELECT max(id) FROM claims));
  PERFORM setval(pg_get_serial_sequence('claim_photos', 'id'), (SELECT max(id) FROM claim_photos));
  PERFORM setval(pg_get_serial_sequence('claim_status_history', 'id'), (SELECT max(id) FROM claim_status_history));
  PERFORM setval(pg_get_serial_sequence('sample_requests', 'id'), (SELECT max(id) FROM sample_requests));
  PERFORM setval(pg_get_serial_sequence('sample_request_items', 'id'), (SELECT max(id) FROM sample_request_items));

  -- hook ของงานอื่น (ตารางใน migration 5NN ที่ต้องล้าง/seed ใหม่ตอน reset)
  FOR r IN SELECT p.proname FROM pg_proc p
            WHERE p.pronamespace = 'public'::regnamespace AND p.proname LIKE 'reset\_hook\_%' AND p.pronargs = 0
            ORDER BY p.proname LOOP
    EXECUTE format('SELECT public.%I()', r.proname);
  END LOOP;

  SELECT jsonb_build_object(
    'companies', (SELECT count(*) FROM companies),
    'users', (SELECT count(*) FROM users),
    'products', (SELECT count(*) FROM products),
    'delivery_addresses', (SELECT count(*) FROM delivery_addresses),
    'orders', (SELECT count(*) FROM orders),
    'order_status_history', (SELECT count(*) FROM order_status_history),
    'payments', (SELECT count(*) FROM payments),
    'claims', (SELECT count(*) FROM claims),
    'claim_status_history', (SELECT count(*) FROM claim_status_history),
    'claim_photos', (SELECT count(*) FROM claim_photos),
    'sample_requests', (SELECT count(*) FROM sample_requests),
    'sample_request_items', (SELECT count(*) FROM sample_request_items),
    'factory_holiday', (SELECT count(*) FROM factory_holiday)
  ) INTO v_counts;
  RETURN v_counts;
END
$fn$;

SELECT reset_test_data('2026-10-11T10:00:00+07:00');
